<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {batchRunLabels,parseBatchExecution,parseBatchVerification,type Batch,type BatchCheck,type BatchExecution,type BatchRun} from './sync-batch';
const props=defineProps<{batch:Batch;check:BatchCheck|null;disabled:boolean;syncActive:boolean}>(),emit=defineEmits<{authenticationRequired:[]}>();
const ack=ref(false),busy=ref(false),consumed=ref(false),result=ref<BatchExecution|null>(null),verification=ref<BatchRun|null>(null),verifyUncertain=ref(false),error=ref(''),readAt=ref('');
const eligible=computed(()=>props.check?.batch_id===props.batch.id&&props.check.status==='verified'&&!!props.check.snapshot);
let active=true,generation=0,controller:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined;
const current=(n:number)=>active&&n===generation;
function invalidate(){generation++;controller?.abort();clearTimeout(timer);busy.value=false;ack.value=false}
async function response(path:string,body?:unknown){const n=generation;const r=await fetch('/api/sync/resolution-batches/'+props.batch.id+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',signal:controller?.signal,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(!current(n))throw new DOMException('旧请求','AbortError');if(r.status===401){stop();emit('authenticationRequired');throw Error('登录已失效')}return r}
async function execution(post=false){if(!active||busy.value||props.disabled)return;if(post&&(!eligible.value||!ack.value||consumed.value||props.syncActive))return;const n=++generation;clearTimeout(timer);controller=new AbortController();busy.value=true;if(post)consumed.value=true;
 try{const r=await response('/execution',post?{check_id:props.check!.id,confirm:true}:undefined);if(!current(n))return;if(!post&&r.status===404){error.value='尚未读到原执行批次，不会自动提交。';return}if(!r.ok)throw Error((await r.text()).slice(0,1000)||'执行记录暂不可读');const data=await r.json();if(!current(n))return;result.value=parseBatchExecution(data,props.batch,result.value);consumed.value=true;ack.value=false;readAt.value=new Date().toISOString();error.value='';if(result.value.run.status==='running')timer=setTimeout(()=>{void execution()},2000)}catch(e){if(current(n))error.value=(e instanceof Error?e.message:String(e))+'；请读取原执行记录，不会自动重发。'}finally{if(current(n))busy.value=false}}
async function verify(post=false){if(!active||busy.value||props.disabled)return;if(post&&(verifyUncertain.value||props.syncActive||result.value?.run.status!=='verification_pending'||verification.value?.status==='running'||verification.value?.status==='complete'))return;const n=++generation;clearTimeout(timer);controller=new AbortController();busy.value=true;if(post)verifyUncertain.value=true;
 try{const r=await response('/verification',post?{}:undefined);if(!current(n))return;if(!post&&r.status===404){verifyUncertain.value=false;error.value='尚未读到整体复核，不会自动启动。';return}if(!r.ok)throw Error((await r.text()).slice(0,1000)||'完整复核暂不可读');const data=await r.json();if(!current(n))return;verification.value=parseBatchVerification(data,props.batch,result.value);verifyUncertain.value=false;error.value='';if(verification.value.status==='running')timer=setTimeout(()=>{void verify()},2000)}catch(e){if(current(n))error.value=(e instanceof Error?e.message:String(e))+'；请只读查询整体复核，不会自动重提。'}finally{if(current(n))busy.value=false}}
function reset(){invalidate();result.value=null;verification.value=null;consumed.value=false;verifyUncertain.value=false;error.value='';readAt.value=''}
function stop(){active=false;invalidate()}
function restore(){active=true}
watch(()=>props.batch.id,reset);watch(()=>props.check?.id,()=>ack.value=false);watch(()=>props.disabled,v=>{if(v)invalidate()});
onMounted(()=>{window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore)});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore)});
</script>
<template><section class="batch-execution"><h3>确认执行固定批次</h3><p class="muted">核对通过后还需明确确认。按固定顺序串行执行；失败或未知会停止后续项目。重复提交读取同一个已准入批次。</p><label class="ack"><input v-model="ack" data-testid="batch-execute-ack" type="checkbox" :disabled="busy||disabled||syncActive||!eligible||consumed"/>我已核对全部方案、固定副本路径和影响范围，确认执行此批次。</label><div class="actions"><button class="button primary" data-testid="batch-execute" :disabled="busy||disabled||syncActive||!eligible||!ack||consumed" @click="execution(true)">确认执行整批</button><button class="button secondary compact" data-testid="batch-execution-read" :disabled="busy||disabled" @click="execution()">读取原批次进度</button></div><p v-if="busy" role="status">正在提交或读取…</p><p v-if="error" role="alert" class="notice danger">{{error}}</p><section v-if="result" data-testid="batch-execution-result"><h4>{{verification?.status==='complete'?'本批次已关联完整复核':batchRunLabels[result.run.status]}}</h4><p class="muted">父运行 {{result.run.id}} · 条目确认 {{result.run.confirmed}} / {{result.run.step_count}}<br>准入 UTC {{result.run.started_at_utc}} · 结束 UTC {{result.run.finished_at_utc||'尚无结束记录'}}<br>本页读取 UTC {{readAt}}</p><p v-if="result.run.error">{{result.run.error}}</p><div class="table-wrap"><table><thead><tr><th>顺序 / 项目</th><th>子项结果</th><th>步骤确认</th><th>回执</th></tr></thead><tbody><tr v-for="(item,i) in result.items" :key="item.decision_id"><td>{{i+1}} · {{batch.items[i]?.root}}</td><!-- Visible QA found stale waiting labels after batch completion; derive only the display, preserving receipts. --><td>{{verification?.status==='complete'?'已关联整批复核':batchRunLabels[item.run.status]}}<small>{{item.run.error}}</small></td><td>{{item.run.confirmed}} / {{item.run.step_count}}</td><td><a class="button secondary compact" :href="'/api/sync/runs/'+item.run.id+'?export=1'" target="_blank" rel="noopener">步骤与事件</a></td></tr></tbody></table></div><p class="muted">准入时间不代表每项已开始写入；实际开始与未启动原因见独立事件。执行完成仍需整批复核才更新共同基线。</p><a class="button secondary compact" :href="'/api/sync/runs/'+result.run.id+'?export=1'" target="_blank" rel="noopener">查看父批次证据</a></section><h3>完整复核与共同基线</h3><p class="muted">全部所选输出仍一致且同步范围没有剩余变化时，才提交新基线。完成关联是当次观察的历史证据。</p><div class="actions"><button class="button primary" data-testid="batch-verify" :disabled="busy||disabled||syncActive||verifyUncertain||result?.run.status!=='verification_pending'||verification?.status==='running'||verification?.status==='complete'" @click="verify(true)">完整复核并建立基线</button><button class="button secondary compact" data-testid="batch-verification-read" :disabled="busy||disabled" @click="verify()">读取整体复核 / 完成关联</button></div><section v-if="verification" data-testid="batch-verification-result"><strong>{{batchRunLabels[verification.status]}}</strong><p>复核 {{verification.id}}<br>开始 UTC {{verification.started_at_utc}}<br>完成 UTC {{verification.finished_at_utc||'尚未完成'}}</p><p v-if="verification.error">{{verification.error}}</p><a class="button secondary compact" :href="'/api/sync/runs/'+verification.id+'?export=1'" target="_blank" rel="noopener">完整复核与基线证据</a></section></section></template>
<style scoped>.batch-execution{border-top:1px solid #dce5ef;padding-top:12px;margin-top:18px}.actions{display:flex;gap:10px;flex-wrap:wrap}.ack{display:flex;align-items:flex-start;gap:8px;margin:12px 0}.ack input{margin-top:4px}p{overflow-wrap:anywhere}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px;text-align:left;margin:12px 0}th,td{padding:8px 10px;border-bottom:1px solid #e4eaf2;vertical-align:top}th{background:#f5f7fb}small{display:block;color:#65748b;margin-top:4px}</style>
